<template><div class="purchase-print"><nav><button @click="print">打印 / 保存PDF</button><button @click="$router.back()">返回</button></nav><p v-if="error" role="alert">{{ error }}</p><p v-else-if="!records.length">正在加载采购单…</p><article v-for="p in records" :key="p.id"><h1>采购单</h1><header><b>{{ p.po_no }}</b><span>供应商：{{ p.supplier }}</span><span>关联订单：{{ p.order_no||'备货采购' }}</span><span>下单日期：{{ fmtDate(p.order_date) }}</span><span>预计到货：{{ fmtDate(p.expect_date) }}</span></header><table><thead><tr><th>物料名称</th><th>规格</th><th>单位</th><th>采购数量</th><th>单价</th><th>金额</th></tr></thead><tbody><tr v-for="i in p.items" :key="i.id"><td>{{ i.name }}</td><td>{{ i.spec||'—' }}</td><td>{{ i.unit }}</td><td>{{ i.qty }}</td><td>{{ money(i.price) }}</td><td>{{ money(i.amount) }}</td></tr></tbody></table><p class="amount">合计：¥{{ money(p.total_amount) }}</p><pre>{{ p.remark }}</pre><footer>采购确认：________________　　供应商确认：________________</footer></article></div></template>
<script setup>
import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {api} from '../api';import {fmtDate} from '../utils/time';
const route=useRoute(),records=ref([]),error=ref(''),money=v=>Number(v||0).toFixed(2);const print=()=>window.print();
onMounted(async()=>{try{const ids=[...new Set(String(route.params.id).split(','))];if(!ids.length||ids.length>50||ids.some(id=>!/^\d+$/.test(id)))throw Error('采购单编号无效或超过50张');records.value=await Promise.all(ids.map(id=>api.purchase(id)));}catch(e){error.value=e.message;}});
</script>
<style scoped>
.purchase-print{max-width:1000px;margin:24px auto;background:var(--surface);color:var(--ink);padding:24px;}nav{display:flex;gap:10px;margin-bottom:24px;}button{border:1px solid var(--line);background:var(--surface);color:var(--ink);padding:8px 16px;border-radius:4px;cursor:pointer;}article{padding:24px 0;break-after:page;}h1{text-align:center;font-size:24px;}header{display:flex;flex-wrap:wrap;gap:12px 25px;margin:20px 0;font-size:13px;}table{border-collapse:collapse;width:100%;}td,th{border:1px solid var(--line);padding:10px;font-size:13px;text-align:left;}th{background:var(--surface-2);}pre{font:inherit;white-space:pre-wrap;overflow-wrap:anywhere;}.amount{text-align:right;}footer{margin-top:40px;font-size:13px;}@media print{.purchase-print{max-width:none;margin:0;padding:0;color:#000;background:#fff;}nav{display:none;}article:last-child{break-after:auto;}td,th{border-color:#888;background:#fff;}}
</style>
